args.sparql:
SELECT DISTINCT ?parent ?parentLabel ?gender ?parentDesc WHERE {
  { dbr:Ottaviano_Riario dbo:parent ?parent } UNION { dbr:Ottaviano_Riario dbp:parents ?parent }
  OPTIONAL { ?parent rdfs:label ?parentLabel . FILTER(lang(?parentLabel) = 'en') }
  OPTIONAL { ?parent dbo:gender ?gender }
  OPTIONAL { ?parent dbo:abstract ?parentDesc . FILTER(lang(?parentDesc) = 'en') }
}

SELECT DISTINCT ?grandfather ?grandfatherLabel ?abstract WHERE {
  { dbr:Caterina_Sforza dbo:parent ?grandfather } UNION { dbr:Caterina_Sforza dbp:parents ?grandfather }
  OPTIONAL { ?grandfather rdfs:label ?grandfatherLabel . FILTER(lang(?grandfatherLabel) = 'en') }
  OPTIONAL { ?grandfather dbo:abstract ?abstract . FILTER(lang(?abstract) = 'en') }
}

SELECT DISTINCT ?maternalGrandfather ?maternalGrandfatherLabel WHERE {
  dbr:Ottaviano_Riario dbo:parent ?mother .
  ?mother dbo:parent ?maternalGrandfather .
  OPTIONAL { ?maternalGrandfather rdfs:label ?maternalGrandfatherLabel . FILTER(lang(?maternalGrandfatherLabel) = 'en') }
}

SELECT DISTINCT ?maternalGrandfather ?maternalGrandfatherLabel WHERE {
  dbr:Ottaviano_Riario dbo:parent ?mother .
  ?mother dbo:parent ?maternalGrandfather .
  OPTIONAL { ?maternalGrandfather rdfs:label ?maternalGrandfatherLabel . FILTER(lang(?maternalGrandfatherLabel) = 'en') }
}

output.sparql:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT ?maternalGrandfather ?maternalGrandfatherLabel WHERE {
  dbr:Ottaviano_Riario dbo:parent ?mother .
  ?mother dbo:parent ?maternalGrandfather .
  OPTIONAL {
    ?maternalGrandfather rdfs:label ?maternalGrandfatherLabel .
    FILTER(lang(?maternalGrandfatherLabel) = 'en')
  }
}

